function db(){const r=cp.spawnSync('docker',['compose','-p','foodywesria','-f','/Users/stev/htdoc/docker_foody_wesria/docker-compose.yml','exec','-T','php-tech','php','tests/e2e/seed-unhappy-paths.php','--snapshot'],{input:JSON.stringify(fixture),encoding:'utf8',maxBuffer:20*1024*1024});assert.equal(r.status,0,'Read-only campaign snapshot failed');assert.ok(r.stdout.trim().startsWith('{'),'Reconciliation helper did not return JSON; inspect private runtime output');const d=JSON.parse(r.stdout);assert.deepEqual(d.reconciliation_errors,[],'Stock reconciliation mismatch');return d;}
function rows(s,table){return s.tables['vmod_'+table]||[];}
function unchanged(before,label='Rejected operation has no persisted effect'){const after=db();assert.equal(hash(after.tables),hash(before.tables),label);note(label,{before:hash(before.tables),after:hash(after.tables)});return after;}
function record(s,table,id){return rows(s,table).find(r=>Number(r.id)===Number(id));}
function business(s){return Object.fromEntries(Object.entries(s.tables).filter(([k])=>k.startsWith('vmod_erp_')));}
async function shot(name,selector){const file=output+'/'+name+'-'+Date.now()+'.png';if(options.repair){await page.evaluate(selector=>document.querySelector(selector||'#request-error:not(.d-none)')?.scrollIntoView({behavior:'instant',block:'start'}),selector??null);await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));const capture=await page.cdp('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});await fs.writeFile(file,Buffer.from(capture.data,'base64'));}else await page.screenshot({path:file,raw:true});report.artifacts.push({case:current?.id,attemptId:current?.attemptId,runnerSha256,appManifestSha256,file,sha256:hash(await fs.readFile(file)),inspected:false});return file;}
