async function freshStock(label,quantity='10'){const location=await catalogue('locations',{code:label+'-'+crypto.randomBytes(3).toString('hex'),name:label+' isolated stock'},{branch_id:fixture.a.branch_id});const po=await newPO(quantity);await approvePO(po);const grn=await newGRN(po,quantity,label+'-'+crypto.randomUUID(),location);await action('purchasing::onConfirm');return{location,po,grn};}
function balance(s,location){return rows(s,'erp_stock_balances').find(r=>Number(r.location_id)===Number(location)&&Number(r.product_id)===Number(fixture.product_id));}
let interceptionTrace=[];
async function pausedRequest(){for(let i=0;i<80;i++){const events=await browserEvents();interceptionTrace.push(...events.filter(e=>['Network.loadingFailed','Fetch.requestPaused'].includes(e.method)));const e=events.find(e=>e.method==='Fetch.requestPaused');if(e)return e.params;await new Promise(r=>setTimeout(r,100));}throw new Error('No intercepted campaign request observed');}
async function loseResponse(selector,path,verify){await page.cdp('Fetch.enable',{patterns:[{urlPattern:base+path+'*',requestStage:'Response'}]});try{await page.click(selector+' button[type="submit"]');const pause=await pausedRequest();assert.equal(pause.responseStatusCode,200);assert.equal(pause.request.method,'POST');verify();await page.cdp('Fetch.failRequest',{requestId:pause.requestId,errorReason:'ConnectionReset'});for(let i=0;i<30;i++){const ev=await browserEvents();if(ev.some(e=>e.method==='Network.loadingFailed'))break;await new Promise(r=>setTimeout(r,100));}if(options.repair)await page.waitForFunction(()=>document.querySelector('#request-error')?.textContent.includes('Save outcome unknown'));const ui=await page.evaluate(()=>({error:document.querySelector('#request-error:not(.d-none)')?.textContent?.trim()??'',state:document.querySelector('#document-detail .badge')?.textContent,disabled:[...document.querySelectorAll('#document-detail button')].map(b=>b.disabled)}));note('Committed HTTP response deliberately lost',{status:pause.responseStatusCode,ui});if(options.repair){const popupPromise=page.waitForEvent('popup');await page.click('#request-error a:last-child');const checkPage=await popupPromise;await checkPage.waitForSelector('#document-detail');assert.match(await checkPage.evaluate(()=>document.querySelector('#document-detail').innerText),/confirmed|dispatched/);await checkPage.close();note('Visible record check in another tab confirms saved state before retry');assert.match(ui.error,/Save outcome unknown/);assert.ok(ui.disabled.every(d=>!d));assert.equal(await page.evaluate(()=>document.querySelectorAll('[data-request-notice].alert-success').length),0);assert.equal(await page.evaluate(()=>document.querySelector('#request-error a:last-child').target),'_blank');}if(!ui.error)finding('Lost response leaves stale document status without an actionable error','must-have UX',ui);await shot(current.id+'-lost-response');}finally{await page.cdp('Fetch.disable');}}
