 cases.H48=async()=>{await owner();const po=await newPO('1'),url='/purchasing?id='+po,number=record(db(),'erp_purchase_orders',po).number;const h=await page.cdp('Page.getNavigationHistory'),back=h.entries[h.currentIndex].id;await logout();await login('b');await workspace('b');const f=await page.cdp('Page.getNavigationHistory'),forward=f.entries[f.currentIndex].id;async function traverse(entryId){const marker=crypto.randomUUID();await page.evaluate(value=>window.__hybridLeaving=value,marker);await page.cdp('Page.navigateToHistoryEntry',{entryId});await page.waitForFunction(value=>window.__hybridLeaving!==value&&document.readyState==='complete',marker,{timeout:15000});}await traverse(back);const viewed=await page.evaluate(()=>({url:location.pathname+location.search,text:document.body.innerText.slice(0,1500)}));note('Exact browser history entry across identity switch',{...viewed,cachedDocumentVisible:viewed.text.includes(number)});await shot('H48-history-back');if(viewed.text.includes(number))finding('Browser history retains prior-account document content','Decision needed',{recommendation:'Fresh requests remain protected. Decide whether cache-history concealment is required.'});await traverse(forward);assert.equal(new URL(await page.url()).pathname,'/');assert.equal(await page.evaluate(()=>document.querySelector('.page-heading h1').innerText),record(db(),'core_companies',fixture.b.company_id).name);await shot('H48-history-forward');const denied=await page.fetch(url);assert.ok([403,404].includes(denied.status));assert.ok(!denied.body.includes(number));await go('/');await seen('current-identity-home','body');};
