 async function armHistory(){await page.evaluate(()=>{window.__historyRestored=false;addEventListener('pageshow',e=>{window.__historyRestored=e.persisted;});const nativeFetch=window.fetch;window.fetch=function(url,options){if(options?.headers?.['X-AJAX-HANDLER']==='identity::onCheckContext'){window.fetch=nativeFetch;return new Promise((resolve,reject)=>{window.__historyProbe={release:()=>nativeFetch.call(window,url,options).then(resolve,reject),fail:()=>reject(new TypeError('Campaign transport failure'))};});}return nativeFetch.call(this,url,options);};});}
 async function historyForm(){await owner();await go('/purchasing?new=1');await page.selectOption('#po-supplier',String(fixture.party_id));await page.selectOption('[name="lines[0][offer_id]"]',String(fixture.offer_id));await page.fill('#po-notes','Keep unsaved history values');await page.focus('#po-notes');await armHistory();return {entry:await historyEntry(),values:await form('#purchase-form')};}
 async function holdHistory(entry){await backTo(entry);await page.waitForFunction(()=>!!window.__historyProbe,undefined,{timeout:8000});assert.equal(await page.evaluate(()=>getComputedStyle(document.querySelector('.page')).display),'none');assert.equal(await page.evaluate(()=>window.__historyRestored),true);await shot(current.id+'-content-concealed','#history-recovery');}
