// Read-only supplement: call with the campaign report and guarded db() snapshot.
// Does not replace browser evidence or reconstruct unavailable pre-race snapshots.
function hybridReadOnlyAssertions(report, s) {
  const results = [];
  const all = name => s.tables['vmod_' + name] || [];
  const decimal = value => { const [a,b=''] = String(value).split('.'); return BigInt(a + b.padEnd(4,'0')); };
  const details = audit => typeof audit.details === 'string' ? JSON.parse(audit.details) : audit.details;
  for (let n=29; n<=41; n++) {
    const id='H'+n, c=report.cases.find(x=>x.id===id);
    if (!c || !['pass','fail'].includes(c.disposition) || !c.finished) {
      results.push({id,status:'not checked',reason:'Journey has no completed current attempt'}); continue;
    }
    const made = name => all(name).filter(r=>(c.createdRows?.['vmod_'+name]||[]).includes(r.id));
    const one = name => { const rs=made(name); assert.equal(rs.length,1,id+': one '+name); return rs[0]; };
    const ops=made('erp_operations'), audits=made('core_audits');
    const race=(c.checks||[]).find(x=>x.label==='Independent-session race');
    const opsFor = action => ops.filter(o=>o.action===action);
    const movements=made('erp_stock_movements');
    const quantitySum=rs=>rs.reduce((a,r)=>a+decimal(r.quantity),0n);
    const checkBalance=(onHand,reserved)=>{const b=one('erp_stock_balances');assert.equal(b.on_hand,onHand,id+' physical');assert.equal(b.reserved,reserved,id+' reserved');};
    const checkAuditCount=(action,count)=>{assert.equal(opsFor(action).length,count,id+' operation count '+action);assert.equal(audits.filter(a=>a.action===action).length,count,id+' audit count '+action);};
    try {
      // Every committed document/stock operation must have exactly its matching operation audit.
      for(const op of ops){assert.ok(op.result_id,id+' no incomplete operation');const match=audits.filter(a=>a.action===op.action&&Number(details(a)?.operation_id)===Number(op.id));assert.equal(match.length,1,id+' operation audit uniqueness');assert.equal(Number(details(match[0]).id),Number(op.result_id),id+' audit result identity');}
      for(const m of movements)assert.ok(ops.some(o=>o.id===m.operation_id),id+' movement belongs to successful operation');
      const receipts=made('erp_goods_receipts'), deliveries=made('erp_delivery_orders');
      const receiptItems=made('erp_goods_receipt_items'), deliveryItems=made('erp_delivery_order_items');
      if(n===29){
        assert.equal(receipts.length,2);assert.ok(receipts.every(g=>g.state==='confirmed'));
        assert.deepEqual(made('erp_purchase_orders').map(p=>p.state),['completed','completed']);
        assert.deepEqual(movements.map(m=>m.quantity).sort(),['3.0000','4.0000']);
        for(const g of receipts){const items=receiptItems.filter(i=>i.goods_receipt_id===g.id);assert.equal(items.length,1);const ms=movements.filter(m=>m.receipt_item_id===items[0].id);assert.equal(ms.length,1);assert.equal(ms[0].action,'receipt');assert.equal(ms[0].quantity,items[0].base_quantity);}
        checkBalance('7.0000','0.0000');checkAuditCount('goodsreceipt.confirmed',2);
      }
      if(n===30){
        assert.ok(race);assert.equal(one('erp_purchase_orders').state,'completed');assert.equal(quantitySum(movements),decimal('3'));
        assert.equal(receipts.filter(g=>g.state==='confirmed').length,1);checkAuditCount('goodsreceipt.confirmed',1);
        if(race.browserStatus===200){assert.equal(receipts.length,1);checkAuditCount('purchaseorder.draft',0);}else{assert.equal(receipts.length,2);assert.equal(receipts.filter(g=>g.state==='voided').length,1);checkAuditCount('purchaseorder.draft',1);}
      }
      if(n===31){assert.ok(race);assert.equal(one('erp_purchase_orders').state,'closed_short');assert.equal(quantitySum(movements),decimal(race.browserStatus===200?'7':'4'));assert.equal(receipts.filter(g=>g.state==='confirmed').length,race.browserStatus===200?2:1);checkAuditCount('purchaseorder.closed_short',1);}
      if(n===32||n===37){
        assert.ok(race);const grn=n===32,docs=grn?receipts:deliveries,items=grn?receiptItems:deliveryItems;
        const original=docs.find(d=>!d.replaces_id),replacement=docs.find(d=>d.replaces_id===original?.id);
        assert.equal(docs.length,2);assert.ok(original&&replacement);assert.equal(original.state,'voided');assert.equal(replacement.state,grn?'confirmed':'dispatched');
        const fk=grn?'goods_receipt_id':'delivery_order_id',mkey=grn?'receipt_item_id':'delivery_item_id';
        const oldItems=items.filter(i=>i[fk]===original.id),newItems=items.filter(i=>i[fk]===replacement.id);assert.equal(oldItems.length,1);assert.equal(newItems.length,1);
        assert.equal(oldItems[0].quantity,grn?'10.0000':'4.0000');
        const winner=race.browserStatus===200?(grn?'8.0000':'3.0000'):(grn?'7.0000':'2.0000');assert.equal(newItems[0].quantity,winner);
        const action=grn?'goodsreceipt.corrected':'deliveryorder.corrected';checkAuditCount(action,1);
        const correction=opsFor(action)[0],ms=movements.filter(m=>m.operation_id===correction.id);assert.equal(ms.length,2);
        const reversal=ms.find(m=>m.action===(grn?'reversal':'dispatch_reversal')),posted=ms.find(m=>m.action===(grn?'receipt':'dispatch'));assert.ok(reversal&&posted);assert.equal(reversal[mkey],oldItems[0].id);assert.equal(posted[mkey],newItems[0].id);
        assert.equal(decimal(reversal.quantity),decimal(grn?'-10':'4'));assert.equal(decimal(posted.quantity),decimal(winner)*(grn?1n:-1n));
        if(grn)checkBalance(winner,'0.0000');else checkBalance(race.browserStatus===200?'7.0000':'8.0000',race.browserStatus===200?'3.0000':'4.0000');
      }
      if(n===33){const po=one('erp_purchase_orders');assert.equal(po.state,'completed');assert.equal(receipts.length,2);const old=receipts.find(g=>g.state==='voided'),fresh=receipts.find(g=>g.state==='confirmed');assert.ok(old&&fresh);assert.equal(fresh.revision_id,po.revision_id);assert.notEqual(old.revision_id,po.revision_id);assert.equal(movements.length,1);assert.equal(movements[0].quantity,'4.0000');assert.equal(receiptItems.find(i=>i.id===movements[0].receipt_item_id).goods_receipt_id,fresh.id);}
      if(n===34){for(const [prefix,count]of[['purchase',3],['sales',2]]){assert.equal(made('erp_'+prefix+'_orders').length,count);assert.equal(made('erp_'+prefix+'_order_revisions').length,count);assert.equal(made('erp_'+prefix+'_order_items').length,count);checkAuditCount(prefix+'order.saved',count);}assert.equal(ops.length,5);assert.equal(movements.length,0);}
      if(n===35){checkBalance('3.0000','0.0000');checkAuditCount('goodsreceipt.corrected',1);assert.equal(receipts.filter(g=>g.state==='voided').length,1);assert.equal(receipts.filter(g=>g.state==='confirmed').length,1);}
      if(n===36){assert.equal(one('erp_sales_orders').state,'completed');assert.equal(one('erp_delivery_orders').state,'dispatched');checkBalance('4.0000','0.0000');checkAuditCount('salesorder.saved',1);}
      if(n===38){assert.ok(race);assert.equal(one('erp_sales_orders').state,'closed_short');checkBalance(race.browserStatus===200?'6.0000':'8.0000','0.0000');assert.equal(deliveries.filter(d=>d.state==='dispatched').length,race.browserStatus===200?2:1);assert.equal(deliveries.filter(d=>d.state==='voided').length,race.browserStatus===200?0:1);checkAuditCount('salesorder.closed_short',1);}
      if(n===39){const so=one('erp_sales_orders');assert.equal(so.state,'completed');checkBalance('5.0000','0.0000');assert.equal(deliveries.length,2);const old=deliveries.find(d=>d.state==='voided'),fresh=deliveries.find(d=>d.state==='dispatched');assert.ok(old&&fresh);assert.equal(fresh.revision_id,so.revision_id);assert.notEqual(old.revision_id,so.revision_id);const ms=movements.filter(m=>m.action==='dispatch');assert.equal(ms.length,1);assert.equal(ms[0].quantity,'-5.0000');assert.equal(deliveryItems.find(i=>i.id===ms[0].delivery_item_id).delivery_order_id,fresh.id);}
      if(n===40){assert.ok(race);assert.equal(one('erp_sales_orders').state,'approved');checkBalance(race.browserStatus===200?'10.0000':'5.0000',race.browserStatus===200?'6.0000':'5.0000');checkAuditCount('salesorder.approved',1);}
      if(n===41){const so=one('erp_sales_orders');assert.equal(so.state,'closed_short');assert.ok(so.first_dispatch_at);checkBalance('10.0000','0.0000');assert.equal(one('erp_delivery_orders').state,'voided');assert.equal(one('erp_delivery_order_items').quantity,'6.0000');assert.equal(movements.filter(m=>m.action==='dispatch_reversal').length,1);checkAuditCount('deliveryorder.corrected',1);checkAuditCount('salesorder.closed_short',1);}
      results.push({id,status:'pass',attemptId:c.attemptId,checks:'Persisted document identities, case-specific quantities, operation/audit linkage and expected row counts'});
    } catch(error){results.push({id,status:'fail',attemptId:c.attemptId,error:error.message});}
  }
  return {results,limitations:['Current-state checks do not reconstruct unavailable pre-race snapshots, establish transient UI behavior, or prove SQL lock waits.','Original immutable quantities are checked against known journey inputs, not independent pre-operation hashes.','Cases with later legitimate modifications to their created records need explicit reconciliation rather than treating drift as a product failure.']};
}

// CAMPAIGN_EXECUTION
if(options.nativeDenials){
 await owner();current=report.cases.find(c=>c.id==='H26');const ids=current.createdRows.vmod_erp_products,product=rows(db(),'erp_products').find(p=>ids.includes(p.id));await go('/catalogue/products?new=1');await page.fill('#sku',product.sku);await page.fill('#name','Duplicate identity rejected');await page.fill('#base_uom','kg');await invalid('#catalogue-form');const duplicateText=await page.evaluate(()=>document.body.innerText);assert.match(duplicateText,/already|taken|exists|unique/i);note('Supplemental visible duplicate rejection',{message:duplicateText.slice(-1200)});await shot('H26-native-duplicate-denial');await go('/catalogue/products?q='+encodeURIComponent(product.sku));await shot('H26-native-existing-record-recovery');current=null;
 await owner();current=report.cases.find(c=>c.id==='H14');const own=current.createdRows.vmod_erp_invoice_references,refs=references(db()),voided=refs.find(r=>own.includes(r.id)&&r.state==='voided'&&refs.some(a=>a.state==='active'&&a.active_number===r.number.toUpperCase()));assert.ok(voided);const active=refs.find(r=>r.active_number===voided.number.toUpperCase());await go('/invoice-references?id='+voided.id);await page.fill('form[data-request="invoiceReferences::onRestore"] [name=reason]','Visible conflict check');const before=db();await clickComplete('form[data-request="invoiceReferences::onRestore"] button');assert.equal(await page.evaluate(()=>document.documentElement.dataset.uatComplete),'409');unchanged(before);assert.match(await page.evaluate(()=>document.querySelector('#request-error').innerText),/active invoice reference already uses this number/);await shot('H14-native-restore-denial');await go('/invoice-references?id='+active.id);await shot('H14-retained-active-record-recovery');current=null;await persist();
}

if(options.reloadEvidence){await owner();for(const[id,path,table,state]of[['H06','receiving','erp_goods_receipts','confirmed'],['H07','delivery','erp_delivery_orders','dispatched']]){current=report.cases.find(c=>c.id===id);const own=current.createdRows['vmod_'+table],matches=rows(db(),table).filter(r=>own.includes(r.id)&&r.state===state&&!r.replaces_id).sort((a,b)=>a.id-b.id);assert.ok(matches.length);const documentId=matches[0].id;await go('/'+path+'?id='+documentId);await page.reload();const text=await page.evaluate(()=>document.querySelector('#document-detail').innerText);assert.ok(text.includes(state));note('Supplemental exact lost-response original reloaded',{documentId,state});await shot(id+'-original-reloaded');current=null;}await persist();}

await persist();
if(options.setup){await setup();await persist();console.log('Principal UI setup ready', {company:fixture.a.company_id,po:fixture.po_id,grn:fixture.grn_id});}
const selected=(options.cases??'').split(',').filter(Boolean).map(x=>options.hybrid?'H'+x.replace(/^H/,'').padStart(2,'0'):x.padStart(2,'0'));
for(const id of selected){if(report.haltWrites)throw new Error('Campaign stopped: reconcile preserved evidence before further writes');if(!cases[id]){const c=report.cases[Number(id.replace(/^H/,''))-1];c.disposition='blocked';c.error='Journey not yet implemented';await persist();continue;}await runCase(id,cases[id]);}
if(options.hybrid&&!options.historyRepair){const receipt=hybridReadOnlyAssertions(report,db());await fs.writeFile(output+'/inspection/persisted-'+Date.now()+'.json',JSON.stringify(receipt,null,2));console.log('Read-only supplemental assertions',receipt.results);}
await persist();console.log({spaceId:task.spaceId,report:output+'/report.json',counts:report.cases.reduce((a,c)=>(a[c.disposition]=(a[c.disposition]??0)+1,a),{})});
